import { gsap } from 'gsap';
import { Group } from 'three/webgpu';
import { } from 'three/tsl';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const node = new Group();
  node.name = config.id ?? 'thumbnail-card';

  // Store resources for cleanup
  const cleanupResources = {
    gltf: null,
    primitives: [],
    timelines: [],
    handlers: [],
  };

  // Load GLB mesh
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (gltf && gltf.scene) {
        node.add(gltf.scene);
        cleanupResources.gltf = gltf;
      }
    });
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const instance = ctx.primitives[prim.name](node, prim.params || {});
        cleanupResources.primitives.push(instance);
      }
    }
  }

  // Event handlers
  const baseY = node.position.y;

  const hoverHandler = () => {
    // Cancel any existing hover timeline
    const existing = cleanupResources.timelines.find(t => t._prismHover);
    if (existing) {
      existing.kill();
      cleanupResources.timelines = cleanupResources.timelines.filter(t => t !== existing);
    }

    const tl = gsap.timeline({
      onComplete: () => {
        cleanupResources.timelines = cleanupResources.timelines.filter(t => t !== tl);
      },
    });
    tl._prismHover = true; // flag for cleanup

    tl.to(
      node.position,
      { y: baseY + 0.15, duration: 0.3, ease: 'power3.out' },
    ).to(
      node.position,
      { y: baseY, duration: 0.3, ease: 'power3.inOut', delay: 0.1 },
    );

    cleanupResources.timelines.push(tl);
  };

  const clickHandler = () => {
    ctx.emit('hub-features.select', {});
  };

  node.userData.handlers = {
    hover: hoverHandler,
    click: clickHandler,
  };

  // Cleanup function
  node.userData.cleanup = () => {
    // Dispose GLTF resources
    if (cleanupResources.gltf) {
      const disposeNode = (obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
        if (obj.texture) obj.texture.dispose();
      };
      cleanupResources.gltf.scene.traverse(disposeNode);
      if (cleanupResources.gltf.scene.parent) {
        cleanupResources.gltf.scene.parent.remove(cleanupResources.gltf.scene);
      }
      cleanupResources.gltf = null;
    }

    // Cleanup primitives
    for (const prim of cleanupResources.primitives) {
      if (prim && typeof prim.cleanup === 'function') {
        prim.cleanup();
      }
    }
    cleanupResources.primitives.length = 0;

    // Kill GSAP timelines
    for (const tl of cleanupResources.timelines) {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    }
    cleanupResources.timelines.length = 0;

    // Clear handlers
    node.userData.handlers = {};
  };

  return node;
}
